func kojoStr(s string) *string { return &s }

func (e kojoExpect) check(t *testing.T, stream, got string) {
	t.Helper()
	if e.exact != nil && got != *e.exact {
		t.Errorf("%s: want exactly %q, got %q", stream, *e.exact, got)
	}
	for _, sub := range e.contains {
		if !strings.Contains(got, sub) {
			t.Errorf("%s: want it to contain %q, got %q", stream, sub, got)
		}
	}
	if e.regex != "" && !regexp.MustCompile(e.regex).MatchString(got) {
		t.Errorf("%s: want it to match %q, got %q", stream, e.regex, got)
	}
	if n := strings.Count(got, "\n"); n < e.minLines {
		t.Errorf("%s: want at least %d lines, got %d", stream, e.minLines, n)
	}
}

